import { Alarms } from '@app/alarms/shared';
import { browser_api } from '@app/browser_api';
import {
  getLocalStorageData,
  setLocalStorageData,
} from '@app/storage/local/shared';
import { LocalStorageKey } from '@app/storage/local/types/sharedTypes';
import { logger } from '@utils/logger';
import { LocalNotification } from './types';
import { shouldShowMedia } from '@content/utils/shouldShowMedia';
import { detectBrowser } from '@app/utils/detectBrowser';
import { PRIORITY_LANGUAGE } from '@app/i18n/constants';
import { messageDispatcher } from '@app/infrastructure/messageDispatcher';
import { MessageHandler } from '@app/infrastructure/types';
import { Actions } from '@app/actions/shared';
import { exhaustiveCheck } from '@utils/exhaustiveCheck';
import { navigateToExtensionPage } from '@background/utils/navigateToExtensionPage';
import { getNotifications } from '@api/getNotifications';
import { getMetaApiData } from '@utils/metaApiData';

export class NotificationService {
  private static instance: NotificationService;
  private isShowingNotification = false;

  constructor() {
    if (NotificationService.instance) {
      return NotificationService.instance;
    }
    NotificationService.instance = this;
  }

  public async init() {
    this.setAlarmListener();
    this.setActionListeners();
    await this.setupAlarms();
  }

  private setAlarmListener() {
    if (browser_api.alarms.onAlarm.hasListener(this.alarmListener)) {
      browser_api.alarms.onAlarm.removeListener(this.alarmListener);
    }
    browser_api.alarms.onAlarm.addListener(this.alarmListener);
  }

  private alarmListener = async (alarm: browser_api.Alarms.Alarm) => {
    if (alarm.name === Alarms.FetchNotifications) {
      await this.fetchAndFilterNotifications();
    } else if (alarm.name === Alarms.ProcessNotificationQueue) {
      await this.processQueue();
    }
  };

  private setActionListeners() {
    messageDispatcher.register(
      Actions.NotificationAction,
      this.notificationActionHandler,
    );
  }

  private async setupAlarms() {
    const { localNotificationsConfig: config } = await getMetaApiData();
    if (!config) {
      logger.error(
        `NotificationService: localNotificationsConfig is not defined`,
      );
      return;
    }

    const fetchAlarm = await browser_api.alarms.get(Alarms.FetchNotifications);
    if (!fetchAlarm) {
      browser_api.alarms.create(Alarms.FetchNotifications, {
        periodInMinutes: config.fetchIntervalMin,
      });
    }
    const processAlarm = await browser_api.alarms.get(
      Alarms.ProcessNotificationQueue,
    );
    if (!processAlarm) {
      browser_api.alarms.create(Alarms.ProcessNotificationQueue, {
        periodInMinutes: config.displayIntervalMin,
      });
    }
    await this.fetchAndFilterNotifications();
  }

  private async fetchAndFilterNotifications() {
    try {
      const [
        { localNotificationsConfig: config },
        { notificationsLastUpdatedMs },
      ] = await Promise.all([
        getMetaApiData(),
        getLocalStorageData(LocalStorageKey.NotificationsLastUpdatedMs),
      ]);

      if (!config) {
        logger.error(
          `NotificationService: localNotificationsConfig is not defined`,
        );
        return;
      }

      const now = Date.now();
      if (
        now - (notificationsLastUpdatedMs ?? 0) <
        config.fetchIntervalMin * 60 * 1000
      ) {
        return;
      }

      const notifications = await getNotifications();

      await setLocalStorageData({
        [LocalStorageKey.NotificationsData]: notifications,
        [LocalStorageKey.NotificationsLastUpdatedMs]: now,
      });

      logger.info('NotificationService: Notifications updated');

      setTimeout(() => this.processQueue(), config.initialDelaySec * 1000);
    } catch (error) {
      logger.error('NotificationService: Fetch error', error);
    }
  }

  private async processQueue() {
    if (this.isShowingNotification) return;

    this.isShowingNotification = true;

    try {
      const [
        {
          notificationsData,
          shownNotificationIds,
          lastNotificationShownMs,
          hasPremium,
          userId,
          currentLocale,
        },
        {
          localNotificationsConfig: config,
          mediaMaxVersionChrome,
          mediaMaxVersionFirefox,
        },
      ] = await Promise.all([
        getLocalStorageData([
          LocalStorageKey.NotificationsData,
          LocalStorageKey.ShownNotificationIds,
          LocalStorageKey.LastNotificationShownMs,
          LocalStorageKey.HasPremium,
          LocalStorageKey.UserId,
          LocalStorageKey.CurrentLocale,
        ]),
        getMetaApiData(),
      ]);

      if (!notificationsData?.length) return;

      if (!userId) return;

      if (!config) {
        logger.error(
          `NotificationService: localNotificationsConfig is not defined`,
        );
        return;
      }

      const now = Date.now();
      const lastShown = lastNotificationShownMs ?? 0;
      if (now - lastShown < config.displayIntervalMin * 60000) return;

      const currentVersion = browser_api.runtime.getManifest().version;
      const isFirefox = detectBrowser() === 'firefox';
      const shouldShow = shouldShowMedia(
        currentVersion,
        isFirefox,
        mediaMaxVersionChrome,
        mediaMaxVersionFirefox,
      );
      if (!shouldShow) {
        logger.info(
          `NotificationService: current version ${currentVersion} > maxAdvVersion`,
        );
        return;
      }

      const shownIds = shownNotificationIds ?? [];
      const validShownIds = shownIds.filter((id) =>
        notificationsData?.some((n) => n.id === id),
      );
      const userPlan = hasPremium ? 'premium' : 'free';
      const userLang =
        (currentLocale ?? PRIORITY_LANGUAGE) === 'ru' ? 'ru' : 'en';

      const nextNotification = notificationsData.find((n) => {
        if (validShownIds.includes(n.id)) return false;
        if (
          Boolean(n.audience) &&
          n.audience !== 'all' &&
          n.audience !== userPlan
        )
          return false;
        if (n.lang !== userLang) return false;

        return true;
      });

      if (nextNotification) {
        const sent = await this.showNotification(nextNotification);

        if (sent) {
          const newShownIds = [...validShownIds, nextNotification.id];

          await setLocalStorageData({
            [LocalStorageKey.ShownNotificationIds]: newShownIds,
            [LocalStorageKey.LastNotificationShownMs]: now,
          });
        }
      }
    } catch (error) {
      logger.error('NotificationService: Process queue error', error);
    } finally {
      this.isShowingNotification = false;
    }
  }

  private async showNotification(
    notification: LocalNotification,
  ): Promise<boolean> {
    try {
      const tabs = await browser_api.tabs.query({
        active: true,
        currentWindow: true,
      });

      const activeTab = tabs?.[0];

      if (!activeTab?.id) {
        logger.info('NotificationService: No active tab found');
        return false;
      }
      await messageDispatcher.sendToTab(activeTab.id, {
        action: Actions.ShowNotification,
        payload: { ...notification, buttons: [notification.button] },
      });
      logger.info(
        `NotificationService: Sent notification ${notification.id} to tab ${activeTab.id}`,
      );

      return true;
    } catch (error) {
      logger.error('NotificationService: Send message error', error);

      return false;
    }
  }

  private notificationActionHandler: MessageHandler<Actions.NotificationAction> =
    async (message) => {
      const { url, actionType } = message.payload;
      logger.info(`NotificationService: Handling action type ${actionType}`);
      switch (actionType) {
        case 'open_url':
          if (url) await browser_api.tabs.create({ url });
          break;
        case 'open_extension_page':
          if (url) await navigateToExtensionPage(url);
          break;
        case 'dismiss':
          break;
        default:
          return exhaustiveCheck(actionType);
      }
    };
}
