import { getConfigsUrl } from '@utils/getConfigsUrl';
import { configsClient } from '@api/configsClient';
import { logger } from '@utils/logger';
import type { getNotificationsResponse, getNotificationType } from './types';

export const getNotifications: getNotificationType = async () => {
  try {
    const url = await getConfigsUrl(process.env.NOTIFICATIONS_API_URL);

    if (!url) {
      throw new Error('getNotifications url is not provided');
    }

    return await configsClient
      .get<getNotificationsResponse>(url.toString())
      .json();
  } catch (error) {
    logger.error('getNotifications: error', error);
    throw error;
  }
};
