import { Actions } from '@app/actions/shared';
import { MessageHandler } from '@app/infrastructure/types';
import { logger } from '@utils/logger';
import {
  getVideoTime,
  getPendingRedirect,
  clearPendingRedirect,
} from '@background/redirect/utils';
import { messageDispatcher } from '@app/infrastructure/messageDispatcher';

export const videoOpenerReadyHandler: MessageHandler<
  Actions.VideoOpenerReady
> = async (_message, { tab }) => {
  const tabId = tab?.id;
  if (tabId === undefined) return;

  const { watchUrl, videoId } = getPendingRedirect(tabId) || {};
  if (!watchUrl || !videoId) return;

  clearPendingRedirect(tabId);

  try {
    const time = await getVideoTime(watchUrl);

    messageDispatcher.sendToTab(tabId, {
      action: Actions.DirectVideoOpen,
      payload: {
        watchUrl,
        videoId,
        time,
      },
    });
  } catch (error) {
    logger.error('[VideoOpenerReady] Error sending DirectVideoOpen', error);
  }
};
