import { browser_api } from '@app/browser_api';
import { Feature } from '@app/features/types/Feature';
import { getPACData } from '@background/pac-script/utils/getPACData';
import { LocalStorageKey } from '@app/storage/local/types/sharedTypes';
import { StoredState } from '@ulta-plus/extension-feature-toggle';

function isStoredState(value: unknown): value is StoredState {
  return (
    typeof value === 'object' &&
    value !== null &&
    'featuresList' in value &&
    typeof (value as any).featuresList === 'object'
  );
}

export async function onFeatureStoreV2Changed(
  changes: Record<string, browser_api.Storage.StorageChange>,
) {
  const featureStoreChange = changes[LocalStorageKey.FeatureStoreV2];

  if (
    !featureStoreChange ||
    !isStoredState(featureStoreChange.newValue) ||
    !isStoredState(featureStoreChange.oldValue)
  )
    return;

  const newFeatures = featureStoreChange.newValue.featuresList;
  const oldFeatures = featureStoreChange.oldValue.featuresList;

  if (newFeatures[Feature.PACLite] !== oldFeatures[Feature.PACLite]) {
    await getPACData({
      shouldRefetch: true,
    });
  }
}
