import { versionStringToNumber } from '@popup/shared/helpers/versionStringToNumber';
/**
 * mediaMaxVersionChrome && mediaMaxVersionFirefox.
 * Версии расширения ниже этих версий и/или равные им считаются валидными для показа медиа
 * */
export function shouldShowMedia(
  currentVersion: string,
  isFirefox: boolean,
  mediaMaxVersionChrome?: string,
  mediaMaxVersionFirefox?: string,
): boolean {
  if (isFirefox && mediaMaxVersionFirefox) {
    return (
      versionStringToNumber(currentVersion) <=
      versionStringToNumber(mediaMaxVersionFirefox)
    );
  } else if (mediaMaxVersionChrome) {
    return (
      versionStringToNumber(currentVersion) <=
      versionStringToNumber(mediaMaxVersionChrome)
    );
  }
  return false;
}
