import { getFeaturesDataV2 } from '@utils/featuresData';
import { Feature } from '../types/Feature';

import { detect } from 'detect-browser';
import { browser_api } from '@app/browser_api';
import { logger } from '@utils/logger';
import { getDeviceId } from '@app/storage/utils/getDeviceId';
import {
  getLocalStorageData,
  setLocalStorageData,
} from '@app/storage/local/shared';
import { LocalStorageKey } from '@app/storage/local/types/sharedTypes';
import { InitOptions, StoredState } from '@ulta-plus/extension-feature-toggle';

export async function getInitialConfig(): Promise<InitOptions> {
  const manifest = browser_api.runtime.getManifest();
  const browser = detect();
  const browserName = browser?.name || 'unknown';
  const browserVersion = browser?.version || 'unknown';
  const deviceId = await getDeviceId();

  function getContext() {
    return {
      appVersion: manifest.version,
      browserName,
      browserVersion,
      deviceId,
    };
  }

  function setStorage(data: StoredState) {
    return setLocalStorageData({ [LocalStorageKey.FeatureStoreV2]: data });
  }

  async function getStorage() {
    const { featureStoreV2 } = await getLocalStorageData(
      LocalStorageKey.FeatureStoreV2,
    );

    return featureStoreV2 ?? null;
  }

  logger.info('browserName', browserName);
  logger.info('browserVersion', browserVersion);

  return {
    features: Object.values(Feature),
    getConfig: getFeaturesDataV2,
    getContext,
    setStorage,
    getStorage,
  };
}
