import { getConfigsUrl } from 'src/utils';
import { configsClient } from './configsClient';
import { FeatureConfigResponse } from '@ulta-plus/extension-feature-toggle';

export async function fetchFeaturesDataV2(): Promise<FeatureConfigResponse> {
  const featuresApiUrl = await getConfigsUrl(process.env.FEATURE_LIST_URL_V2);

  if (!featuresApiUrl) {
    throw new Error('No features API URL provided');
  }

  const data = await configsClient
    .get<FeatureConfigResponse>(featuresApiUrl.toString())
    .json();

  return data;
}
